class Solution:

	def NBitBinary(self, N):
		one = 1
		zero = 0
		op = '1'
		answer = []
		self.Solve(one, zero, op, N - 1, answer)
		return answer

	def Solve(self, one, zero, op, N, answer):
		if N == 0:
			answer.append(op)
			return
		elif one > zero:
			op1 = op + '1'
			op2 = op + '0'
			self.Solve(one + 1, zero, op1, N - 1, answer)
			self.Solve(one, zero + 1, op2, N - 1, answer)
		elif one == zero:
			op = op + '1'
			self.Solve(one + 1, zero, op, N - 1, answer)
